import { useEffect, useRef, useState } from 'react';
import { Toolbar } from '@kerfjs/ui/toolbar';
import { MenuHeader } from '@kerfjs/ui/menu-header';
import { MenuItem } from '@kerfjs/ui/menu-item';
import { ResizableRegion, wireResizableRegions } from '@kerfjs/ui/resizable-region';
import '@kerfjs/ui/layout.css';
import './app-shell.css';

type PaneSizes = { navigation: number; inspector: number };
const loadSizes = (): PaneSizes => JSON.parse(localStorage.getItem('workspace-pane-sizes') ?? '{\"navigation\":240,\"inspector\":320}');

export function AppShell() {
  const root = useRef<HTMLDivElement>(null);
  const [sizes, setSizes] = useState(loadSizes);

  useEffect(() => {
    if (!root.current) return;
    const dispose = wireResizableRegions(root.current);
    return dispose;
  }, []);

  function persist(next: PaneSizes) {
    setSizes(next);
    localStorage.setItem('workspace-pane-sizes', JSON.stringify(next));
  }

  return (
    <div ref={root} className="app-shell kui-layout">
      <Toolbar aria-label="Application toolbar" className="app-toolbar">
        <button type="button">New item</button>
        <button type="button" aria-label="Open account menu">Account</button>
      </Toolbar>
      <div className="shell-body">
        <ResizableRegion aria-label="Navigation width" value={sizes.navigation} min={192} max={360} onValueChange={(navigation: number) => persist({ ...sizes, navigation })}>
          <nav className="navigation-scroll kui-sidebar" aria-label="Workspace navigation">
            <section className="kui-sidebar-section">
              <MenuHeader>Workspace</MenuHeader>
              <MenuItem selected href="/inbox">Inbox</MenuItem>
              <MenuItem href="/projects">Projects</MenuItem>
            </section>
            <section className="kui-sidebar-section">
              <MenuHeader>Saved</MenuHeader>
              <MenuItem href="/recent">Recent</MenuItem>
            </section>
          </nav>
        </ResizableRegion>
        <main className="workspace-scroll kui-page" tabIndex={-1}>
          <h1>Inbox</h1>
          <p>Application content belongs here.</p>
        </main>
        <ResizableRegion side="end" aria-label="Inspector width" value={sizes.inspector} min={256} max={480} onValueChange={(inspector: number) => persist({ ...sizes, inspector })}>
          <aside className="inspector-scroll kui-pane" aria-label="Inspector">
            <h2>Inspector</h2>
            <p>Select an item to inspect it.</p>
          </aside>
        </ResizableRegion>
      </div>
    </div>
  );
}

