.app-shell { block-size: 100dvh; display: grid; grid-template-rows: auto minmax(0, 1fr); }
.app-toolbar { flex-wrap: wrap; }
.shell-body { display: grid; grid-template-columns: auto minmax(0, 1fr) auto; min-block-size: 0; }
.navigation-scroll, .workspace-scroll, .inspector-scroll { block-size: 100%; overflow: auto; }
.workspace-scroll, .inspector-scroll { padding: var(--kui-space-page); }
@media (max-width: 700px) {
  .shell-body { grid-template-columns: minmax(0, 1fr); }
  .shell-body > :first-child, .shell-body > :last-child { display: none; }
  .workspace-scroll { min-inline-size: 0; }
}
@media (prefers-reduced-motion: reduce) { * { scroll-behavior: auto; } }
@media (prefers-contrast: more) { .shell-body { border-color: CanvasText; } }
